import React from 'react';
import { NavigationContainer } from '@react-navigation/native';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { ActivityIndicator, View, Text, StyleSheet } from 'react-native';
import LoginScreen from './screens/LoginScreen';
import RegisterScreen from './screens/RegisterScreen';
import ProfileScreen from './screens/ProfileScreen';
import { AuthProvider, useAuth } from './context/AuthContext';
import NFCScreen from './screens/NFCScreen';
import NFCRegister from './screens/NFCRegister';
import AdminScreen from './screens/AdminScreen';

const Stack = createNativeStackNavigator();

function LoadingScreen() {
  return (
    <View style={styles.loadingContainer}>
      <ActivityIndicator size="large" color="#001dad" />
      <Text style={styles.loadingText}>Loading...</Text>
    </View>
  );
}

function AppNavigator() {
  const { user, isLoading, isAdmin, isEmployee, isAuthenticated } = useAuth();

  if (isLoading) {
    return <LoadingScreen />;
  }

  console.log('🔄 Navigation State:', {
    isAuthenticated,
    userType: user?.type,
    isAdmin,
    isEmployee,
    userEmail: user?.email,
    isLoading
  });
  if (isLoading) {
    return <LoadingScreen />;
  }

  return (
    <Stack.Navigator screenOptions={{
      headerStyle: {
        backgroundColor: '#001dad',
      },
      headerTintColor: '#fff',
      headerTitleStyle: {
        fontWeight: 'bold',
      },
      animation: 'slide_from_right',
    }}>
      {isAuthenticated ? (
        <>
          <Stack.Screen 
            name="Profile" 
            component={ProfileScreen} 
            options={{ 
              headerShown: false,
              gestureEnabled: false,
            }}
          />
          
          <Stack.Screen 
            name="NFCLogin" 
            component={NFCScreen} 
            options={{ 
              title: 'RFID Login',
              headerBackTitle: 'Back',
              headerShown: false,
            }}
          />

          {isAdmin && (
            <>
              <Stack.Screen 
                name="AdminDashboard" 
                component={AdminScreen}
                options={{ 
                  title: 'Admin Dashboard',
                  headerBackTitle: 'Profile',
                  headerShown: false,
                }}
              />
              <Stack.Screen 
                name="NFCRegister" 
                component={NFCRegister} 
                options={{ 
                  title: 'Register RFID Card',
                  headerBackTitle: 'Back'
                }}
              />
              <Stack.Screen 
                name="NFCScreen" 
                component={NFCScreen} 
                options={{ 
                  title: 'RFID Management',
                  headerBackTitle: 'Back',
                }} 
              />
            </>
          )}

          {isEmployee && (
            <>
            </>
          )}
        </>
      ) : (
        <>
          <Stack.Screen 
            name="Login" 
            component={LoginScreen} 
            options={{ 
              headerShown: false,
              gestureEnabled: false,
            }}
          />
          <Stack.Screen 
            name="Register" 
            component={RegisterScreen} 
            options={{ 
              headerShown: false,
              title: 'Create Account',
              headerBackTitle: 'Login'
            }}
          />
          <Stack.Screen 
            name="NFCLogin" 
            component={NFCScreen} 
            options={{ 
              title: 'RFID Login',
              headerBackTitle: 'Back',
              headerShown: false,
            }}
          />
          <Stack.Screen 
            name="NFCRegister" 
            component={NFCRegister} 
            options={{ 
              title: 'Register RFID Card',
              headerBackTitle: 'Back'
            }}
          />
        </>
      )}
    </Stack.Navigator>
  );
}

export default function App() {
  return (
    <AuthProvider>
      <NavigationContainer>
        <AppNavigator />
      </NavigationContainer>
    </AuthProvider>
  );
}

const styles = StyleSheet.create({
  loadingContainer: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: '#f8f9fa',
  },
  loadingText: {
    marginTop: 10,
    fontSize: 16,
    color: '#666',
  },
});