import React, { useState, useEffect } from 'react';
import {View,StyleSheet,Text,TouchableOpacity,TextInput,Alert,ActivityIndicator,ScrollView,} from 'react-native';
import { API_CONFIG, ENDPOINTS } from '../services/api';
import { useAuth } from '../context/AuthContext';
import AsyncStorage from '@react-native-async-storage/async-storage';
import Svg, { Rect, Defs, LinearGradient, Stop } from 'react-native-svg';

export default function RegisterScreen({ navigation }: { navigation: any }) {
  const { login } = useAuth();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [companyName, setCompanyName] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [registrationType, setRegistrationType] = useState<'company' | 'admin'>('company');
  const [existingCompanies, setExistingCompanies] = useState<string[]>([]);
  const [selectedCompany, setSelectedCompany] = useState('');
  const [isCheckingCompany, setIsCheckingCompany] = useState(false);
  const [companyStatus, setCompanyStatus] = useState<'available' | 'not_found' | null>(null);

  useEffect(() => {
    if (registrationType === 'admin') {
      loadExistingCompanies();
    }
  }, [registrationType]);

  useEffect(() => {
    const checkCompanyExistence = async () => {
      if (registrationType === 'admin' && selectedCompany.trim().length >= 2) {
        setIsCheckingCompany(true);
        setCompanyStatus(null);
        
        try {
          const response = await fetch(`${API_CONFIG.BASE_URL}/companies/check-existence`, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
            },
            body: JSON.stringify({
              company_name: selectedCompany.trim(),
            }),
          });

          if (response.ok) {
            setCompanyStatus('available');
          } else {
            setCompanyStatus('not_found');
          }
        } catch (error) {
          console.error('Error checking company:', error);
          setCompanyStatus('not_found');
        } finally {
          setIsCheckingCompany(false);
        }
      } else {
        setCompanyStatus(null);
      }
    };

    const timeoutId = setTimeout(checkCompanyExistence, 1000);
    return () => clearTimeout(timeoutId);
  }, [selectedCompany, registrationType]);

  const loadExistingCompanies = async () => {
    try {
      const storedCompanies = await AsyncStorage.getItem('recentCompanies');
      if (storedCompanies) {
        setExistingCompanies(JSON.parse(storedCompanies));
      }
    } catch (error) {
      console.error('Error loading existing companies:', error);
    }
  };

  const handleRegister = async () => {
    if (registrationType === 'company') {
      if (!companyName || !email || !password || !confirmPassword) {
        Alert.alert('Error', 'Please fill in all fields');
        return;
      }

      if (!email.includes('@')) {
        Alert.alert('Error', 'Please enter a valid email address');
        return;
      }

      if (companyName.length < 2) {
        Alert.alert('Error', 'Company name must be at least 2 characters long');
        return;
      }
    } else {
      if (!selectedCompany || !email || !password || !confirmPassword) {
        Alert.alert('Error', 'Please fill in all fields');
        return;
      }

      if (!email.includes('@')) {
        Alert.alert('Error', 'Please enter a valid email address');
        return;
      }

      if (companyStatus === 'not_found') {
        Alert.alert('Error', 'Company not found. Please check the company name.');
        return;
      }

      if (isCheckingCompany) {
        Alert.alert('Please Wait', 'Still verifying company existence...');
        return;
      }
    }

    if (password.length < 6) {
      Alert.alert('Error', 'Password must be at least 6 characters long');
      return;
    }

    if (password !== confirmPassword) {
      Alert.alert('Error', 'Passwords do not match');
      return;
    }

    setIsLoading(true);
    try {
      if (registrationType === 'company') {
        const response = await fetch(`${API_CONFIG.BASE_URL}${ENDPOINTS.AUTH.ADMIN_REGISTER}`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            company_name: companyName.trim(),
            admin_email: email.trim().toLowerCase(),
            admin_password: password,
          }),
        });

        if (!response.ok) {
          const errorText = await response.text();
          console.error('❌ Server response error:', {
            status: response.status,
            statusText: response.statusText,
            body: errorText
          });
          
          let errorMessage = 'Registration failed';
          try {
            const errorData = JSON.parse(errorText);
            errorMessage = errorData.error || errorMessage;
          } catch (e) {
            errorMessage = errorText || `Server error: ${response.status}`;
          }
          
          throw new Error(errorMessage);
        }

        const data = await response.json();

        await login(data.token, {
          ...data.admin,
          type: 'user',
          company_id: data.company.id,
          company_name: data.company.name
        });

        Alert.alert(
          'Success', 
          `Company "${companyName}" created successfully!\n\nAdmin Account:\n• Email: ${email}\n• Company ID: ${data.company.id}\n\nSave your Company ID - your employees will need it to login.`,
          [
            { 
              text: 'OK', 
              onPress: () => {
                resetForm();
                navigation.navigate('Login');
              }
            }
          ]
        );
      } else {
        const response = await fetch(`${API_CONFIG.BASE_URL}${ENDPOINTS.AUTH.ADD_ADMIN}`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            company_name: selectedCompany.trim(),
            admin_email: email.trim().toLowerCase(),
            admin_password: password,
          }),
        });

        if (!response.ok) {
          const errorText = await response.text();
          let errorMessage = 'Registration failed';
          try {
            const errorData = JSON.parse(errorText);
            errorMessage = errorData.error || errorMessage;
          } catch (e) {
            errorMessage = errorText || `Server error: ${response.status}`;
          }
          
          throw new Error(errorMessage);
        }

        const data = await response.json();

        await login(data.token, {
          ...data.admin,
          type: 'user',
          company_id: data.company.id,
          company_name: data.company.name
        });

        Alert.alert(
          'Success', 
          `Admin account created successfully for "${selectedCompany}"!\n\nYou can now login with your email.`,
          [
            { 
              text: 'OK', 
              onPress: () => {
                resetForm();
                navigation.navigate('Login');
              }
            }
          ]
        );
      }
    } catch (error: any) {
      console.error('Registration error:', error);
      if (error.message?.includes('already exists')) {
        Alert.alert('Registration Failed', 'This email is already registered. Please use a different email.');
      } else if (error.message?.includes('Company not found')) {
        Alert.alert('Registration Failed', 'The selected company was not found. Please check the company name.');
      } else if (error.message?.includes('Admin email already exists')) {
        Alert.alert('Registration Failed', 'This email is already registered as an admin.');
      } else {
        Alert.alert('Registration Failed', error.message || 'Failed to register. Please check your connection and try again.');
      }
    } finally {
      setIsLoading(false);
    }
  };

  const resetForm = () => {
    setEmail('');
    setPassword('');
    setConfirmPassword('');
    setCompanyName('');
    setSelectedCompany('');
    setCompanyStatus(null);
  };

  const toggleRegistrationType = () => {
    const newType = registrationType === 'company' ? 'admin' : 'company';
    setRegistrationType(newType);
    resetForm();
  };

  const isFormValid = () => {
    if (registrationType === 'company') {
      return companyName.trim().length >= 2 && 
             email.includes('@') && 
             password.length >= 6 && 
             password === confirmPassword;
    } else {
      return selectedCompany.trim().length >= 2 && 
             email.includes('@') && 
             password.length >= 6 && 
             password === confirmPassword &&
             companyStatus === 'available';
    }
  };

  const handleCompanySelect = (company: string) => {
    setSelectedCompany(company);
  };

  const getCompanyStatusText = () => {
    if (isCheckingCompany) {
      return 'Checking company...';
    }
    if (companyStatus === 'available') {
      return '✓ Company found';
    }
    if (companyStatus === 'not_found') {
      return '✗ Company not found';
    }
    return '';
  };

  const getCompanyStatusColor = () => {
    if (isCheckingCompany) return '#007AFF';
    if (companyStatus === 'available') return '#34C759';
    if (companyStatus === 'not_found') return '#FF3B30';
    return '#666';
  };

  return (
    <ScrollView contentContainerStyle={styles.scrollContainer}>
      <View style={styles.container}>
        <View style={styles.backgroundContainer}>
          <Svg height="100%" width="100%" style={styles.backgroundSvg}>
            <Defs>
              <LinearGradient id="grad" x1="0%" y1="0%" x2="100%" y2="100%">
                <Stop offset="0.1" stopColor="#ffbf00" stopOpacity="1" />
                <Stop offset="0.3" stopColor="#ff8c00" stopOpacity="1" />
                <Stop offset="0.7" stopColor="#04ded3" stopOpacity="1" />
                <Stop offset="0.5" stopColor="#0463de" stopOpacity="1" />
                <Stop offset="1" stopColor="#02b30e" stopOpacity="1" />
              </LinearGradient>
            </Defs>
            <Rect x="0" y="0" width="100%" height="100%" fill="url(#grad)" />
          </Svg>
        </View>
        <View style={styles.subcontainer}>
          <Text style={styles.title}>
            {registrationType === 'company' ? 'Create New Company' : 'Join Existing Company'}
          </Text>

          <Text style={styles.registrationNote}>
            {registrationType === 'company' 
              ? 'Create a new company with an administrator account. You will receive a Company ID for your employees.'
              : 'Create an additional admin account for an existing company.'}
          </Text>

          <View style={styles.registrationTypeContainer}>
            <Text style={styles.registrationTypeLabel}>Registration Type:</Text>
            <TouchableOpacity 
              style={styles.registrationTypeToggle}
              onPress={toggleRegistrationType}
            >
              <View style={styles.toggleContainer}>
                <View style={[styles.toggleOption, registrationType === 'company' && styles.toggleOptionActive]}>
                  <Text style={[styles.toggleText, registrationType === 'company' && styles.toggleTextActive]}>
                    New Company
                  </Text>
                </View>
                <View style={[styles.toggleOption, registrationType === 'admin' && styles.toggleOptionActive]}>
                  <Text style={[styles.toggleText, registrationType === 'admin' && styles.toggleTextActive]}>
                    Existing Company
                  </Text>
                </View>
              </View>
            </TouchableOpacity>
          </View>

          {registrationType === 'company' ? (
            <>
              <Text style={styles.label}>Company Name *</Text>
              <TextInput
                style={styles.input}
                placeholder="Enter your company name"
                placeholderTextColor='#666'
                value={companyName}
                onChangeText={setCompanyName}
                autoCapitalize="words"
              />
              <Text style={styles.note}>
                This will be your organization's name in the system.
              </Text>
            </>
          ) : (
            <>
              <Text style={styles.label}>Company Name *</Text>
              <TextInput
                style={styles.input}
                placeholder="Enter existing company name"
                placeholderTextColor='#666'
                value={selectedCompany}
                onChangeText={setSelectedCompany}
                autoCapitalize="words"
              />
              
              {selectedCompany.length >= 2 && (
                <Text style={[styles.companyStatus, { color: getCompanyStatusColor() }]}>
                  {getCompanyStatusText()}
                </Text>
              )}
              
              {existingCompanies.length > 0 && (
                <View style={styles.recentCompaniesContainer}>
                  <Text style={styles.recentCompaniesLabel}>Recent Companies:</Text>
                  <ScrollView 
                    horizontal 
                    showsHorizontalScrollIndicator={false}
                    style={styles.recentCompaniesList}
                  >
                    {existingCompanies.map((company) => (
                      <TouchableOpacity
                        key={company}
                        style={[
                          styles.recentCompanyButton,
                          selectedCompany === company && styles.recentCompanyButtonActive
                        ]}
                        onPress={() => handleCompanySelect(company)}
                      >
                        <Text style={[
                          styles.recentCompanyText,
                          selectedCompany === company && styles.recentCompanyTextActive
                        ]}>
                          {company}
                        </Text>
                      </TouchableOpacity>
                    ))}
                  </ScrollView>
                </View>
              )}
              
              <Text style={styles.note}>
                Enter the exact company name you want to join as an admin.
              </Text>
            </>
          )}

          <Text style={styles.label}>Admin Email *</Text>
          <TextInput
            style={styles.input}
            placeholder="Enter admin email address"
            placeholderTextColor='#666'
            value={email}
            onChangeText={setEmail}
            autoCapitalize="none"
            keyboardType="email-address"
            autoComplete="email"
          />

          <Text style={styles.label}>Password *</Text>
          <View style={styles.passwordContainer}>
            <TextInput
              style={styles.passwordInput}
              placeholder="Create admin password"
              placeholderTextColor='#666'
              value={password}
              onChangeText={setPassword}
              secureTextEntry={!showPassword}
              autoComplete="password-new"
            />
            <TouchableOpacity
              style={styles.showPasswordButton}
              onPress={() => setShowPassword(!showPassword)}
            >
              <Text style={styles.showPasswordText}>
                {showPassword ? 'Hide' : 'Show'}
              </Text>
            </TouchableOpacity>
          </View>

          <Text style={styles.label}>Confirm Password *</Text>
          <View style={styles.passwordContainer}>
            <TextInput
              style={styles.passwordInput}
              placeholder="Confirm your password"
              placeholderTextColor='#666'
              value={confirmPassword}
              onChangeText={setConfirmPassword}
              secureTextEntry={!showConfirmPassword}
              autoComplete="password-new"
            />
            <TouchableOpacity
              style={styles.showPasswordButton}
              onPress={() => setShowConfirmPassword(!showConfirmPassword)}
            >
              <Text style={styles.showPasswordText}>
                {showConfirmPassword ? 'Hide' : 'Show'}
              </Text>
            </TouchableOpacity>
          </View>

          <TouchableOpacity
            style={[styles.button, registrationType === 'company' ? styles.companyButton : styles.adminButton, (!isFormValid() || isLoading) && styles.buttonDisabled]}
            onPress={handleRegister}
            disabled={!isFormValid() || isLoading}>
            {isLoading ? (
              <ActivityIndicator color="#fff" />
            ) : (
              <Text style={styles.buttonText}>
                {registrationType === 'company' ? 'Create Company & Admin' : 'Join Company as Admin'}
              </Text>
            )}
          </TouchableOpacity>

          <TouchableOpacity
            style={styles.switchButton}
            onPress={() => navigation.navigate('Login')}>
            <Text style={styles.switchText}>
              Already have an account? Login
            </Text>
          </TouchableOpacity>
        </View>
      </View>
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  scrollContainer: {
    flexGrow: 1,
  },
  container: {
    backgroundColor: '#001dad',
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    padding: 20,
  },
  subcontainer: {
    backgroundColor: '#ffffff',
    padding: 25,
    borderRadius: 25,
    width: '100%',
    maxWidth: 400,
    borderRightWidth: 4,
    borderRightColor : '#fc0303',
    borderLeftWidth: 4,
    borderLeftColor : '#fc0303',
  },
  title: {
    fontSize: 28,
    fontWeight: 'bold',
    marginBottom: 15,
    textAlign: 'center',
    color: '#333',
  },
  registrationNote: {
    fontSize: 14,
    color: '#666',
    textAlign: 'center',
    marginBottom: 20,
    lineHeight: 18,
  },
  registrationTypeContainer: {
    marginBottom: 20,
  },
  registrationTypeLabel: {
    fontSize: 16,
    color: '#333',
    marginBottom: 8,
    fontWeight: '500',
  },
  registrationTypeToggle: {
    marginBottom: 10,
  },
  toggleContainer: {
    flexDirection: 'row',
    borderWidth: 2,
    borderColor: '#007AFF',
    borderRadius: 10,
    overflow: 'hidden',
  },
  toggleOption: {
    flex: 1,
    padding: 12,
    alignItems: 'center',
    backgroundColor: 'white',
  },
  toggleOptionActive: {
    backgroundColor: '#007AFF',
  },
  toggleText: {
    fontSize: 14,
    fontWeight: '600',
    color: '#007AFF',
  },
  toggleTextActive: {
    color: 'white',
  },
  label: {
    fontSize: 16,
    color: '#333',
    marginBottom: 8,
    fontWeight: '500',
  },
  note: {
    fontSize: 12,
    color: '#666',
    fontStyle: 'italic',
    marginTop: -5,
    marginBottom: 5,
    lineHeight: 16,
  },
  companyStatus: {
    fontSize: 14,
    fontWeight: '600',
    marginTop: -8,
    marginBottom: 15,
    textAlign: "left",
  },
  input: {
    borderWidth: 2,
    borderColor: '#000',
    color: '#333',
    borderRadius: 10,
    padding: 15,
    marginBottom: 10,
    backgroundColor: 'white',
    fontSize: 16,
  },
  recentCompaniesContainer: {
    marginBottom: 15,
  },
  recentCompaniesLabel: {
    fontSize: 14,
    color: '#666',
    marginBottom: 8,
    fontWeight: '500',
  },
  recentCompaniesList: {
    marginHorizontal: -5,
  },
  recentCompanyButton: {
    backgroundColor: '#f0f0f0',
    paddingHorizontal: 12,
    paddingVertical: 8,
    borderRadius: 8,
    borderWidth: 1,
    borderColor: '#ddd',
    marginHorizontal: 5,
    marginBottom: 5,
  },
  recentCompanyButtonActive: {
    backgroundColor: '#007AFF',
    borderColor: '#007AFF',
  },
  recentCompanyText: {
    fontSize: 12,
    color: '#333',
    fontWeight: '500',
  },
  recentCompanyTextActive: {
    color: 'white',
  },
  button: {
    padding: 15,
    borderRadius: 10,
    alignItems: 'center',
    marginBottom: 15,
  },
  companyButton: {
    backgroundColor: '#34C759',
  },
  adminButton: {
    backgroundColor: '#007AFF',
  },
  buttonDisabled: {
    backgroundColor: '#CCCCCC',
  },
  buttonText: {
    color: '#fff',
    fontSize: 16,
    fontWeight: 'bold',
  },
  switchButton: {
    alignItems: 'center',
    padding: 10,
    marginBottom: 15,
  },
  switchText: {
    color: '#007AFF',
    fontSize: 16,
    textDecorationLine: 'underline',
  },
  passwordContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    borderWidth: 2,
    borderColor: '#000',
    borderRadius: 10,
    marginBottom: 20,
    backgroundColor: 'white',
  },
  passwordInput: {
    flex: 1,
    padding: 15,
    fontSize: 16,
    color: '#333',
  },
  showPasswordButton: {
    padding: 15,
    paddingLeft: 10,
  },
  showPasswordText: {
    color: '#007AFF',
    fontWeight: '600',
  },
  infoTitle: {
    fontSize: 14,
    fontWeight: 'bold',
    color: '#333',
    marginBottom: 8,
  },
  infoText: {
    fontSize: 12,
    color: '#666',
    lineHeight: 16,
  },
  backgroundContainer: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
  },
  backgroundSvg: {
    flex: 1,
    width : '100%',
    height : '100%',
  },
});