import React, { createContext, useState, useContext, useEffect, ReactNode, useCallback } from 'react';
import AsyncStorage from '@react-native-async-storage/async-storage';

export type User = {
  id: number;
  email: string;
  company_id: string;
  company_name?: string;
  created_at?: string;
  type: 'user';
};

export type Employee = {
  id: number;
  uid: string;
  first_name: string;
  last_name: string;
  email?: string;
  username: string;
  auth_method: 'rfid' | 'email' | 'username' | 'both';
  type: 'employee';
  company_id: string;
  company_name?: string;
  created_at?: string;
};

type AuthContextType = {
  user: User | Employee | null;
  isLoading: boolean;
  isAuthenticated: boolean;
  login: (token: string, userData: User) => Promise<void>;
  employeeLogin: (token: string, employeeData: Employee) => Promise<void>;
  logout: () => Promise<void>;
  checkAuth: () => Promise<void>;
  getAuthHeaders: () => Promise<HeadersInit_>;
  isAdmin: boolean;
  isEmployee: boolean;
  companyInfo: { id: string; name: string } | null;
  getCompanyHeaders: () => Promise<HeadersInit_>;
};

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | Employee | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [companyInfo, setCompanyInfo] = useState<{ id: string; name: string } | null>(null);

  const isAuthenticated = !!user;
  const isAdmin = user?.type === 'user';
  const isEmployee = user?.type === 'employee';

  const storeCompanyInfo = async (companyId: string, companyName?: string) => {
    try {
      await AsyncStorage.setItem('companyId', companyId);
      if (companyName) {
        await AsyncStorage.setItem('companyName', companyName);
      }
      setCompanyInfo({ id: companyId, name: companyName || 'Unknown Company' });
    } catch (error) {
      console.error('Error storing company info:', error);
    }
  };

  const login = async (token: string, userData: User) => {
    try {
      console.log('🔐 AuthContext: Starting admin login...');
      
      await AsyncStorage.setItem('adminToken', token);
      await AsyncStorage.setItem('adminData', JSON.stringify(userData));
      await AsyncStorage.setItem('userToken', token);
      await AsyncStorage.setItem('userData', JSON.stringify(userData));
      
      if (userData.company_id) {
        await storeCompanyInfo(userData.company_id, userData.company_name);
      }
      
      setUser(userData);
      console.log('✅ AuthContext: Admin login completed, user set:', userData.email);
    } catch (error) {
      console.error('❌ AuthContext: Admin login error:', error);
      throw error;
    }
  };

  const employeeLogin = async (token: string, employeeData: Employee) => {
    try {
      console.log('🔐 AuthContext: Starting employee login...');
      
      await AsyncStorage.setItem('employeeToken', token);
      await AsyncStorage.setItem('employeeData', JSON.stringify(employeeData));
      await AsyncStorage.setItem('userToken', token);
      await AsyncStorage.setItem('userData', JSON.stringify(employeeData));
      
      if (employeeData.company_id) {
        await storeCompanyInfo(employeeData.company_id, employeeData.company_name);
      }
      
      setUser(employeeData);
      console.log('✅ AuthContext: Employee login completed, user set:', employeeData.email);
    } catch (error) {
      console.error('❌ AuthContext: Employee login error:', error);
      throw error;
    }
  };

  const logout = useCallback(async () => {
    try {
      await AsyncStorage.multiRemove([
        'userToken',
        'userData',
        'adminToken', 
        'adminData',
        'employeeToken',
        'employeeData',
        'companyId',
        'companyName',
        'recentCompanies'
      ]);
      setUser(null);
      setCompanyInfo(null);
    } catch (error) {
      console.error('Logout error:', error);
    }
  }, []);

  const checkAuth = useCallback(async () => {
    try {
      console.log('🔄 AuthContext: Checking authentication...');
      
      const adminToken = await AsyncStorage.getItem('adminToken');
      const employeeToken = await AsyncStorage.getItem('employeeToken');
      const userToken = await AsyncStorage.getItem('userToken');
      
      const adminData = await AsyncStorage.getItem('adminData');
      const employeeData = await AsyncStorage.getItem('employeeData');
      const userData = await AsyncStorage.getItem('userData');
      
      const companyId = await AsyncStorage.getItem('companyId');
      const companyName = await AsyncStorage.getItem('companyName');

      if (companyId) {
        setCompanyInfo({ id: companyId, name: companyName || 'Unknown Company' });
      }

      if (adminToken && adminData) {
        console.log('🔐 AuthContext: Restoring admin session');
        const parsedAdmin = JSON.parse(adminData);
        setUser(parsedAdmin);
      } else if (employeeToken && employeeData) {
        console.log('👤 AuthContext: Restoring employee session');
        const parsedEmployee = JSON.parse(employeeData);
        setUser(parsedEmployee);
      } else if (userToken && userData) {
        console.log('🔙 AuthContext: Restoring legacy session');
        const parsedUser = JSON.parse(userData);
        setUser(parsedUser);
        
        if (parsedUser.company_id && !companyId) {
          await storeCompanyInfo(parsedUser.company_id, parsedUser.company_name);
        }
      } else {
        console.log('🚫 AuthContext: No valid session found');
        setUser(null);
      }
    } catch (error) {
      console.error('❌ AuthContext: Auth check error:', error);
      await logout();
    } finally {
      setIsLoading(false);
    }
  }, [logout]);

  const getAuthHeaders = async (): Promise<HeadersInit_> => {
    try {
      const adminToken = await AsyncStorage.getItem('adminToken');
      const employeeToken = await AsyncStorage.getItem('employeeToken');
      const userToken = await AsyncStorage.getItem('userToken');
      
      const token = adminToken || employeeToken || userToken;
      
      return {
        'Content-Type': 'application/json',
        ...(token && { Authorization: `Bearer ${token}` }),
      };
    } catch (error) {
      console.error('Error getting auth headers:', error);
      return { 'Content-Type': 'application/json' };
    }
  };

  const getCompanyHeaders = async (): Promise<HeadersInit_> => {
    try {
      const token = await AsyncStorage.getItem('adminToken') || 
                    await AsyncStorage.getItem('employeeToken') || 
                    await AsyncStorage.getItem('userToken');
      
      const companyId = await AsyncStorage.getItem('companyId');
      
      const headers: HeadersInit_ = {
        'Content-Type': 'application/json',
      };
      
      if (token) {
        headers.Authorization = `Bearer ${token}`;
      }
      
      if (companyId) {
        headers['X-Company-ID'] = companyId;
      }
      
      return headers;
    } catch (error) {
      console.error('Error getting company headers:', error);
      return { 'Content-Type': 'application/json' };
    }
  };

  useEffect(() => {
    checkAuth();
  }, [checkAuth]);

  const contextValue: AuthContextType = {
    user,
    isLoading,
    isAuthenticated,
    login,
    employeeLogin,
    logout,
    checkAuth,
    getAuthHeaders,
    isAdmin,
    isEmployee,
    companyInfo,
    getCompanyHeaders,
  };

  return (
    <AuthContext.Provider value={contextValue}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export const useCompany = () => {
  const { companyInfo, user, isAdmin, isEmployee } = useAuth();
  
  const getCompanyId = (): string | null => {
    if (user?.type === 'user') {
      return (user as User).company_id;
    } else if (user?.type === 'employee') {
      return (user as Employee).company_id;
    }
    return companyInfo?.id || null;
  };

  const getCompanyName = (): string => {
    if (user?.type === 'user' && (user as User).company_name) {
      return (user as User).company_name!;
    } else if (user?.type === 'employee' && (user as Employee).company_name) {
      return (user as Employee).company_name!;
    }
    return companyInfo?.name || 'Unknown Company';
  };

  return {
    companyId: getCompanyId(),
    companyName: getCompanyName(),
    companyInfo,
    isAdmin,
    isEmployee,
    hasCompany: !!getCompanyId(),
  };
};