import React, { useState, useEffect, useCallback } from 'react';
import {View,StyleSheet,Text,TouchableOpacity,ScrollView,Alert,ActivityIndicator,RefreshControl} from 'react-native';
import { useAuth, useCompany } from '../context/AuthContext';
import { API_CONFIG, ENDPOINTS } from '../services/api';
import Svg, { Rect, Defs, LinearGradient, Stop } from 'react-native-svg';

interface Employee {
  id: string;
  first_name: string;
  last_name: string;
  email: string;
  username: string;
  uid: string;
  auth_method: string;
  is_active: boolean;
  created_at: string;
  company_id?: string;
}

export default function AdminScreen({ navigation }: { navigation: any }) {
  const { getAuthHeaders, logout } = useAuth();
  const { companyName, companyId } = useCompany(); 
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [actionLoading, setActionLoading] = useState<string | null>(null); 

  const loadEmployees = useCallback(async () => {
    try {
      const headers = await getAuthHeaders();
      console.log('📡 Loading employees for company:', companyId);
      
      const response = await fetch(`${API_CONFIG.BASE_URL}${ENDPOINTS.ADMIN.EMPLOYEES}`, {
        method: 'GET',
        headers,
      });

      if (response.status === 401 || response.status === 403) {
        Alert.alert(
          'Session Expired', 
          'Your admin session has expired. Please log in again.',
          [{ text: 'OK', onPress: logout }]
        );
        return;
      }

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || `Server error: ${response.status}`);
      }

      const data = await response.json();
      console.log('✅ Employees loaded:', data.employees?.length || 0);
      setEmployees(data.employees || []);
    } catch (error) {
      console.error('❌ Load employees error:', error);
      Alert.alert(
        'Error', 
        error instanceof Error ? error.message : 'Failed to load employees data'
      );
    } finally {
      setIsLoading(false);
      setRefreshing(false);
    }
  }, [getAuthHeaders, logout, companyId]); 

  useEffect(() => {
    loadEmployees();
  }, [loadEmployees]);

  const onRefresh = () => {
    setRefreshing(true);
    loadEmployees();
  };

  const handleDeleteEmployee = (employee: Employee) => {
    Alert.alert(
      'Delete Employee',
      `Are you sure you want to delete ${employee.first_name} ${employee.last_name}? This action cannot be undone.`,
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Delete',
          style: 'destructive',
          onPress: () => confirmDeleteEmployee(employee.id)
        }
      ]
    );
  };

  const confirmDeleteEmployee = async (employeeId: string) => {
    setActionLoading(`delete-${employeeId}`);
    
    try {
      const headers = await getAuthHeaders();
      const response = await fetch(
        `${API_CONFIG.BASE_URL}${ENDPOINTS.ADMIN.DELETE_EMPLOYEE(employeeId)}`,
        {
          method: 'DELETE',
          headers,
        }
      );

      if (response.status === 401 || response.status === 403) {
        Alert.alert('Session Expired', 'Please log in again.');
        logout();
        return;
      }

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || 'Failed to delete employee');
      }

      const result = await response.json();
      Alert.alert('Success', result.message);
      
      loadEmployees();
    } catch (error) {
      console.error('❌ Delete employee error:', error);
      Alert.alert('Error', error instanceof Error ? error.message : 'Failed to delete employee');
    } finally {
      setActionLoading(null);
    }
  };

  const handleToggleActive = async (employee: Employee) => {
    setActionLoading(`toggle-${employee.id}`);
    
    try {
      const headers = await getAuthHeaders();
      const response = await fetch(
        `${API_CONFIG.BASE_URL}${ENDPOINTS.ADMIN.TOGGLE_ACTIVE(employee.id)}`,
        {
          method: 'PUT',
          headers,
        }
      );

      if (response.status === 401 || response.status === 403) {
        Alert.alert('Session Expired', 'Please log in again.');
        logout();
        return;
      }

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || 'Failed to update employee status');
      }

      const result = await response.json();
      
      Alert.alert('Success', result.message);
      
      loadEmployees();
    } catch (error) {
      console.error('❌ Toggle active error:', error);
      Alert.alert('Error', error instanceof Error ? error.message : 'Failed to update employee status');
    } finally {
      setActionLoading(null);
    }
  };

  const formatDate = (dateString: string) => {
    if (!dateString) return 'N/A';
    
    try {
      return new Date(dateString).toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'short',
        day: 'numeric'
      });
    } catch (error) {
      return 'Invalid Date';
    }
  };

  const getAuthMethodDisplay = (authMethod: string) => {
    switch (authMethod) {
      case 'rfid': return 'RFID Card';
      case 'email': return 'Email';
      case 'username': return 'Username';
      case 'both': return 'Email & Username';
      default: return authMethod || 'Email';
    }
  };

  const getStatusStats = () => {
    const active = employees.filter(emp => emp.is_active).length;
    const inactive = employees.filter(emp => !emp.is_active).length;
    const total = employees.length;
    
    return { active, inactive, total };
  };

  const navigateToNFCRegister = () => {
    navigation.navigate('NFCRegister');
  };

  const navigateToProfile = () => {
    navigation.navigate('Profile');
  };

  if (isLoading) {
    return (
      <View style={styles.centerContainer}>
        <ActivityIndicator size="large" color="#001dad" />
        <Text style={styles.loadingText}>Loading employees...</Text>
      </View>
    );
  }

  const { active, inactive, total } = getStatusStats();

  return (
    <View style={styles.container}>
      <View style={styles.header}>
        <View style={styles.backgroundContainer}>
          <Svg height="100%" width="100%" style={styles.backgroundSvg}>
            <Defs>
              <LinearGradient id="grad" x1="0%" y1="0%" x2="100%" y2="100%">
                <Stop offset="0.1" stopColor="#ffbf00" stopOpacity="1" />
                <Stop offset="0.3" stopColor="#ff8c00" stopOpacity="1" />
                <Stop offset="0.7" stopColor="#04ded3" stopOpacity="1" />
                <Stop offset="0.5" stopColor="#0463de" stopOpacity="1" />
                <Stop offset="1" stopColor="#02b30e" stopOpacity="1" />
              </LinearGradient>
            </Defs>
            <Rect x="0" y="0" width="100%" height="100%" fill="url(#grad)" />
          </Svg>
        </View>
        <Text style={styles.title}>Admin Dashboard</Text>
        <Text style={styles.subtitle}>{companyName}</Text>
        <Text style={styles.companyId}>Company ID: {companyId}</Text>
      </View>

      <View style={styles.quickActions}>
        <TouchableOpacity 
          style={styles.quickActionButton}
          onPress={navigateToNFCRegister}
        >
          <Text style={styles.quickActionText}>Register RFID</Text>
        </TouchableOpacity>
        
        <TouchableOpacity 
          style={styles.quickActionButton}
          onPress={onRefresh}
        >
          <Text style={styles.quickActionText}>Refresh</Text>
        </TouchableOpacity>
        
        <TouchableOpacity 
          style={styles.quickActionButton}
          onPress={navigateToProfile}
        >
          <Text style={styles.quickActionText}>Profile</Text>
        </TouchableOpacity>
      </View>

      <View style={styles.statsContainer}>
        <View style={styles.statCard}>
          <Text style={styles.statNumber}>{total}</Text>
          <Text style={styles.statLabel}>Total Employees</Text>
        </View>
        <View style={styles.statCard}>
          <Text style={[styles.statNumber, styles.statActive]}>{active}</Text>
          <Text style={styles.statLabel}>Active</Text>
        </View>
        <View style={styles.statCard}>
          <Text style={[styles.statNumber, styles.statInactive]}>{inactive}</Text>
          <Text style={styles.statLabel}>Inactive</Text>
        </View>
      </View>

      <ScrollView
        style={styles.content}
        refreshControl={
          <RefreshControl 
            refreshing={refreshing} 
            onRefresh={onRefresh}
            colors={['#001dad']}
            tintColor="#001dad"
          />
        }
      >
        {employees.length === 0 ? (
          <View style={styles.emptyState}>
            <Text style={styles.emptyStateText}>No Employees Found</Text>
            <Text style={styles.emptyStateSubtext}>
              Register employees using RFID cards or manual registration.
            </Text>
            <TouchableOpacity 
              style={styles.emptyStateButton}
              onPress={navigateToNFCRegister}
            >
              <Text style={styles.emptyStateButtonText}>Register First Employee</Text>
            </TouchableOpacity>
          </View>
        ) : (
          employees.map((employee) => (
            <View key={employee.id} style={styles.employeeCard}>
              <View style={styles.employeeInfo}>
                <View style={styles.nameContainer}>
                  <Text style={styles.employeeName}>
                    {employee.first_name} {employee.last_name}
                  </Text>
                  <View style={[
                    styles.statusBadge,
                    employee.is_active ? styles.activeBadge : styles.inactiveBadge
                  ]}>
                    <Text style={styles.statusText}>
                      {employee.is_active ? 'Active' : 'Inactive'}
                    </Text>
                  </View>
                </View>
                
                <Text style={styles.employeeDetail}>
                  <Text style={styles.detailLabel}>Email: </Text>
                  {employee.email || 'Not set'}
                </Text>
                <Text style={styles.employeeDetail}>
                  <Text style={styles.detailLabel}>Username: </Text>
                  {employee.username || 'Not set'}
                </Text>
                <Text style={styles.employeeDetail}>
                  <Text style={styles.detailLabel}>RFID UID: </Text>
                  {employee.uid}
                </Text>
                <Text style={styles.employeeDetail}>
                  <Text style={styles.detailLabel}>Auth Method: </Text>
                  {getAuthMethodDisplay(employee.auth_method)}
                </Text>
                <Text style={styles.employeeDetail}>
                  <Text style={styles.detailLabel}>Registered: </Text>
                  {formatDate(employee.created_at)}
                </Text>
              </View>

              <View style={styles.actionsContainer}>
                <TouchableOpacity
                  style={[
                    styles.actionButton,
                    employee.is_active ? styles.deactivateButton : styles.activateButton,
                    actionLoading === `toggle-${employee.id}` && styles.buttonDisabled
                  ]}
                  onPress={() => handleToggleActive(employee)}
                  disabled={actionLoading === `toggle-${employee.id}`}
                >
                  {actionLoading === `toggle-${employee.id}` ? (
                    <ActivityIndicator size="small" color="#fff" />
                  ) : (
                    <Text style={styles.actionButtonText}>
                      {employee.is_active ? 'Deactivate' : 'Activate'}
                    </Text>
                  )}
                </TouchableOpacity>

                <TouchableOpacity
                  style={[
                    styles.actionButton, 
                    styles.deleteButton,
                    actionLoading === `delete-${employee.id}` && styles.buttonDisabled
                  ]}
                  onPress={() => handleDeleteEmployee(employee)}
                  disabled={actionLoading === `delete-${employee.id}`}
                >
                  {actionLoading === `delete-${employee.id}` ? (
                    <ActivityIndicator size="small" color="#fff" />
                  ) : (
                    <Text style={styles.actionButtonText}>Delete</Text>
                  )}
                </TouchableOpacity>

              </View>
            </View>
          ))
        )}
      </ScrollView>

      <View style={styles.footer}>
        <TouchableOpacity
          style={styles.refreshButton}
          onPress={loadEmployees}
          disabled={refreshing}
        >
          {refreshing ? (
            <ActivityIndicator color="#fff" />
          ) : (
            <Text style={styles.refreshButtonText}>Refresh List</Text>
          )}
        </TouchableOpacity>
      </View>
    </View>
  );
}

