import React, { useState, useEffect } from 'react';
import {View, Text, StyleSheet, TouchableOpacity, ScrollView, Alert, ActivityIndicator, TextInput } from 'react-native';
import NfcManager, { NfcEvents, TagEvent } from 'react-native-nfc-manager';
import { useAuth } from '../context/AuthContext';
import { API_CONFIG, ENDPOINTS } from '../services/api';
import AsyncStorage from '@react-native-async-storage/async-storage';
import Svg, { Rect, Defs, LinearGradient, Stop } from 'react-native-svg';

type NfcUid = string | number[] | { value: number[] };

export default function NFCLoginScreen({ navigation }: { navigation: any }) {
  const { employeeLogin } = useAuth();
  const [hasNfc, setHasNfc] = useState<boolean | null>(null);
  const [enabled, setEnabled] = useState<boolean | null>(null);
  const [isReading, setIsReading] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [companyNameInput, setCompanyNameInput] = useState('');
  const [recentCompanies, setRecentCompanies] = useState<string[]>([]);

  useEffect(() => {
    loadRecentCompanies();
    checkNfcSupport();
    
    return () => {
      NfcManager.setEventListener(NfcEvents.DiscoverTag, null);
      NfcManager.setEventListener(NfcEvents.SessionClosed, null);
      stopReading();
    };
  }, []);

  const loadRecentCompanies = async () => {
    try {
      const storedCompanies = await AsyncStorage.getItem('recentCompanies');
      if (storedCompanies) {
        setRecentCompanies(JSON.parse(storedCompanies));
      }
    } catch (error) {
      console.error('Error loading recent companies:', error);
    }
  };

  const saveCompanyToRecent = async (companyName: string) => {
    try {
      const updatedCompanies = [
        companyName,
        ...recentCompanies.filter(name => name !== companyName)
      ].slice(0, 5);
      
      setRecentCompanies(updatedCompanies);
      await AsyncStorage.setItem('recentCompanies', JSON.stringify(updatedCompanies));
    } catch (error) {
      console.error('Error saving recent company:', error);
    }
  };

  const checkNfcSupport = async () => {
    try {
      const supported = await NfcManager.isSupported();
      setHasNfc(supported);
      
      if (supported) {
        const nfcEnabled = await NfcManager.isEnabled();
        setEnabled(nfcEnabled);
      }
    } catch (error) {
      Alert.alert('NFC Error', 'Failed to check NFC support');
    }
  };

  const convertUidToString = (uid: NfcUid): string => {
    if (typeof uid === 'string') return uid;
    if (Array.isArray(uid)) {
      return uid.map(byte => byte.toString(16).padStart(2, '0')).join(':').toUpperCase();
    }
    if (typeof uid === 'object' && uid.value) {
      return convertUidToString(uid.value);
    }
    return String(uid);
  };

  const validateCompanyName = (): boolean => {
    if (!companyNameInput.trim()) {
      Alert.alert('Company Name Required', 'Please enter your Company Name');
      return false;
    }
    return true;
  };

  const handleNFCLogin = async (uid: string) => {
    if (isProcessing || !validateCompanyName()) return;

    setIsProcessing(true);
    
    try {
      const response = await fetch(`${API_CONFIG.BASE_URL}${ENDPOINTS.AUTH.NFC_LOGIN}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          uid: uid,
          company_name: companyNameInput.trim()
        }),
      });

      const data = await response.json();

      if (response.ok) {
        await saveCompanyToRecent(companyNameInput);
        await employeeLogin(data.token, { 
          ...data.employee, 
          type: 'employee',
          company_id: data.employee.company_id,
          company_name: data.employee.company_name 
        });
        
        Alert.alert(
          'Success', 
          `Welcome ${data.employee.first_name} ${data.employee.last_name}!`,
          [{ 
            text: 'OK', 
            onPress: () => navigation.reset({
              index: 0,
              routes: [{ name: 'Profile' }],
            })
          }]
        );
      } else {
        handleLoginError(data.error, uid);
      }
    } catch (error) {
      Alert.alert('Connection Error', 'Failed to connect to server');
    } finally {
      setIsProcessing(false);
    }
  };

  const handleLoginError = (error: string, _uid: string) => {
    if (error?.includes('not registered')) {
      Alert.alert(
        'RFID Card Not Registered',
        `This RFID card is not registered in "${companyNameInput}".`,
        [{ text: 'OK' }]
      );
    } else if (error?.includes('Company not found')) {
      Alert.alert(
        'Company Not Found',
        `"${companyNameInput}" was not found. Please check the spelling.`,
        [{ text: 'OK' }]
      );
    } else if (error?.includes('deactivated')) {
      Alert.alert(
        'Account Deactivated',
        'Your account has been deactivated. Contact administrator.',
        [{ text: 'OK' }]
      );
    } else {
      Alert.alert('Login Failed', error || 'Unknown error occurred');
    }
  };

  const startReading = async () => {
    if (!validateCompanyName()) return;

    try {
      setIsReading(true);
      await NfcManager.registerTagEvent();
      
      NfcManager.setEventListener(NfcEvents.DiscoverTag, (tag: TagEvent) => {
        if (tag.id) {
          const uid = convertUidToString(tag.id as NfcUid);
          handleNFCLogin(uid);
        }
      });

      setTimeout(() => {
        if (isReading) {
          stopReading();
          Alert.alert('Scanning Timeout', 'Tap "Start RFID Login" to scan again.');
        }
      }, 30000);

    } catch (error) {
      Alert.alert('NFC Error', 'Failed to start NFC reading');
      setIsReading(false);
    }
  };

  const stopReading = async () => {
    try {
      await NfcManager.unregisterTagEvent();
      setIsReading(false);
    } catch (error) {
      console.error('Error stopping NFC:', error);
    }
  };

  if (hasNfc === null) {
    return (
      <View style={styles.centerContainer}>
        <ActivityIndicator size="large" color="#007AFF" />
        <Text style={styles.loadingText}>Checking NFC support...</Text>
      </View>
    );
  }

  if (!hasNfc) {
    return (
      <View style={styles.centerContainer}>
        <Text style={styles.errorTitle}>NFC Not Supported</Text>
        <Text style={styles.errorText}>Your device doesn't support NFC.</Text>
        <TouchableOpacity 
          style={styles.primaryButton} 
          onPress={() => navigation.navigate('Login')}
        >
          <Text style={styles.buttonText}>Go to Login</Text>
        </TouchableOpacity>
      </View>
    );
  }

  if (!enabled) {
    return (
      <View style={styles.centerContainer}>
        <Text style={styles.errorTitle}>NFC Disabled</Text>
        <Text style={styles.errorText}>Please enable NFC to use RFID login.</Text>
        <TouchableOpacity 
          style={styles.primaryButton} 
          onPress={() => NfcManager.goToNfcSetting()}
        >
          <Text style={styles.buttonText}>Open NFC Settings</Text>
        </TouchableOpacity>
        <TouchableOpacity 
          style={styles.secondaryButton} 
          onPress={() => navigation.navigate('Login')}
        >
          <Text style={styles.secondaryButtonText}>Use Email Login</Text>
        </TouchableOpacity>
      </View>
    );
  }

  return (
    <ScrollView contentContainerStyle={styles.scrollContainer}>
      <View style={styles.container}>
        <View style={styles.backgroundContainer}>
          <Svg height="100%" width="100%" style={styles.backgroundSvg}>
            <Defs>
              <LinearGradient id="grad" x1="0%" y1="0%" x2="100%" y2="100%">
                <Stop offset="0.1" stopColor="#ffbf00" stopOpacity="1" />
                <Stop offset="0.3" stopColor="#ff8c00" stopOpacity="1" />
                <Stop offset="0.7" stopColor="#04ded3" stopOpacity="1" />
                <Stop offset="0.5" stopColor="#0463de" stopOpacity="1" />
                <Stop offset="1" stopColor="#02b30e" stopOpacity="1" />
              </LinearGradient>
            </Defs>
            <Rect x="0" y="0" width="100%" height="100%" fill="url(#grad)" />
          </Svg>
        </View>
        <Text style={styles.title}>RFID Card Login</Text>
        
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>Company Name</Text>
          <TextInput
            style={styles.input}
            placeholder="Enter your company name"
            value={companyNameInput}
            onChangeText={setCompanyNameInput}
            autoCapitalize="words"
          />

          {recentCompanies.length > 0 && (
            <View style={styles.recentContainer}>
              <Text style={styles.recentLabel}>Recent:</Text>
              <View style={styles.recentList}>
                {recentCompanies.map((company) => (
                  <TouchableOpacity
                    key={company}
                    style={styles.recentButton}
                    onPress={() => setCompanyNameInput(company)}
                  >
                    <Text style={styles.recentText}>{company}</Text>
                  </TouchableOpacity>
                ))}
              </View>
            </View>
          )}
        </View>

        <View style={styles.section}>
          <Text style={styles.sectionTitle}>Tap Your RFID Card</Text>
          <Text style={styles.instructions}>
            Hold your RFID card near the back of your device
          </Text>
          
          <View style={styles.statusContainer}>
            <View style={styles.statusIndicator}>
              <View style={[
                styles.statusDot,
                isReading ? styles.statusActive : styles.statusInactive,
              ]} />
              <Text style={styles.statusText}>
                {isReading ? 'Ready to Scan' : 'Tap Start to Begin'}
              </Text>
            </View>
            
            {isProcessing && (
              <View style={styles.processingContainer}>
                <ActivityIndicator size="small" color="#007AFF" />
                <Text style={styles.processingText}>Processing...</Text>
              </View>
            )}
          </View>
          
          <View style={styles.buttonContainer}>
            {!isReading ? (
              <TouchableOpacity 
                style={[
                  styles.primaryButton, 
                  !companyNameInput && styles.buttonDisabled
                ]} 
                onPress={startReading}
                disabled={!companyNameInput}
              >
                <Text style={styles.buttonText}>
                  Start RFID Login
                </Text>
              </TouchableOpacity>
            ) : (
              <TouchableOpacity 
                style={styles.stopButton} 
                onPress={stopReading}
              >
                <Text style={styles.buttonText}>Stop Scanning</Text>
              </TouchableOpacity>
            )}
            
            <TouchableOpacity 
              style={styles.secondaryButton} 
              onPress={() => navigation.navigate('Login')}
            >
              <Text style={styles.secondaryButtonText}>Use Email Login</Text>
            </TouchableOpacity>
          </View>
        </View>
      </View>
    </ScrollView>
  );
}

