import React from 'react';
import {View,StyleSheet,Text,TouchableOpacity,ScrollView,Alert} from 'react-native';
import { useAuth, useCompany } from '../context/AuthContext'; 
import type { Employee, User } from '../context/AuthContext'; 
import Svg, { Rect, Defs, LinearGradient, Stop } from 'react-native-svg';

const isEmployee = (user: any): user is Employee => {
  return user && user.type === 'employee';
};

const isAdminUser = (user: any): user is User => {
  return user && user.type === 'user';
};

export default function ProfileScreen({ navigation }: { navigation: any }) {
  const { user, logout, isEmployee: isEmployeeUser, isAdmin } = useAuth();
  const { companyName, companyId } = useCompany(); 

  const handleLogout = async () => {
    Alert.alert(
      'Logout',
      'Are you sure you want to logout?',
      [
        { text: 'Cancel', style: 'cancel' },
        { 
          text: 'Logout', 
          style: 'destructive',
          onPress: async () => {
            await logout();
          }
        },
      ]
    );
  };

  const handleAdminDashboard = () => {
    navigation.navigate('AdminDashboard');
  };

  const formatUserData = () => {
    if (!user) return [];
    
    const data = [];
    
    if (isEmployeeUser && isEmployee(user)) {
      const employee = user;
      data.push(
        { label: 'Employee ID', value: employee.id?.toString() || 'N/A' },
        { label: 'RFID UID', value: employee.uid || 'N/A' },
        { label: 'First Name', value: employee.first_name || 'N/A' },
        { label: 'Last Name', value: employee.last_name || 'N/A' },
        { label: 'Email', value: employee.email || 'Not set' },
        { label: 'Username', value: employee.username || 'Not set' },
      );
      
      if (companyName) {
        data.push({ label: 'Company', value: companyName });
      }
      
      if (employee.created_at) {
        data.push({ label: 'Registered At', value: new Date(employee.created_at).toLocaleString() });
      }
    } else if (isAdmin && isAdminUser(user)) {
      const admin = user;
      data.push(
        { label: 'Admin ID', value: admin.id?.toString() || 'N/A' },
        { label: 'Email', value: admin.email || 'N/A' },
        { label: 'Role', value: 'Administrator' },
        { label: 'Permissions', value: 'Full System Access' },
      );
      
      if (companyName) {
        data.push({ label: 'Company', value: companyName });
      }
      if (companyId) {
        data.push({ label: 'Company ID', value: companyId });
      }
      
      if (admin.created_at) {
        data.push({ label: 'Account Created', value: new Date(admin.created_at).toLocaleString() });
      }
    }
    
    return data;
  };
  const userData = formatUserData();

  return (
    <View style={styles.container}>        
      <View style={styles.backgroundContainer}>
        <Svg height="100%" width="100%" style={styles.backgroundSvg}>
          <Defs>
            <LinearGradient id="grad" x1="0%" y1="0%" x2="100%" y2="100%">
              <Stop offset="0.1" stopColor="#ffbf00" stopOpacity="1" />
              <Stop offset="0.3" stopColor="#ff8c00" stopOpacity="1" />
              <Stop offset="0.7" stopColor="#04ded3" stopOpacity="1" />
              <Stop offset="0.5" stopColor="#0463de" stopOpacity="1" />
              <Stop offset="1" stopColor="#02b30e" stopOpacity="1" />
            </LinearGradient>
          </Defs>
          <Rect x="0" y="0" width="100%" height="100%" fill="url(#grad)" />
        </Svg>
      </View>

      <View style={styles.header}>
        <View style={styles.userInfo}>
          <Text style={styles.subtitle}>
            {isEmployeeUser 
              ? `${(user as Employee)?.first_name} ${(user as Employee)?.last_name}`
              : (user as User)?.email
            }
          </Text>
          {companyName && (
            <Text style={styles.companyText}>{companyName}</Text>
          )}
        </View>
        <TouchableOpacity 
          style={styles.logoutButton}
          onPress={handleLogout}
        >
          <Text style={styles.logoutButtonText}>Logout</Text>
        </TouchableOpacity>
      </View>

      <ScrollView style={styles.content}>
        <View style={styles.dataCard}>
          <Text style={styles.cardTitle}>
            {isEmployeeUser ? 'Account Information' : 'Administrator Information'}
          </Text>
          
          {userData.map((item, index) => (
            <View 
              key={index} 
              style={[
                styles.dataRow,
                index === userData.length - 1 && styles.lastDataRow
              ]}
            >
              <Text style={styles.dataLabel}>{item.label}:</Text>
              <Text style={[
                styles.dataValue,
                item.label.includes('ID') && styles.monospaceText
              ]}>{item.value}</Text>
            </View>
          ))}
        </View>
        {companyId && (
          <View style={styles.companyCard}>
            <Text style={styles.cardTitle}>Company Information</Text>
            <View style={styles.infoContent}>
              <Text style={styles.infoText}>
                <Text style={styles.boldText}>Company:</Text> {companyName}
              </Text>
              <Text style={styles.infoText}>
                <Text style={styles.boldText}>Company ID:</Text> {companyId}
              </Text>

            {isAdmin && (
              <>
                <TouchableOpacity 
                  style={styles.primaryButton}
                  onPress={handleAdminDashboard}
                >
                  <Text style={styles.primaryButtonText}>Admin Dashboard</Text>
                </TouchableOpacity>
              </>
            )}

            </View>
          </View>
        )}
      </ScrollView>
    </View>
  );
}

