import { View, StyleSheet, Text, TouchableOpacity, TextInput, Alert, ActivityIndicator, ScrollView} from "react-native";
import { useState, useEffect } from "react";
import { useAuth } from '../context/AuthContext';
import { API_CONFIG, ENDPOINTS } from '../services/api';
import AsyncStorage from '@react-native-async-storage/async-storage';
import Svg, { Rect, Defs, LinearGradient, Stop } from 'react-native-svg';
import Keychain from 'react-native-keychain';

export default function LoginScreen({ navigation }: { navigation: any }) {
  const [loginIdentifier, setLoginIdentifier] = useState('');
  const [password, setPassword] = useState('');
  const [companyName, setCompanyName] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const { login, employeeLogin } = useAuth();
  const [showPassword, setShowPassword] = useState(false);
  const [loginType, setLoginType] = useState('employee');
  const [recentCompanies, setRecentCompanies] = useState<string[]>([]);

  useEffect(() => {
    loadRecentCompanies();
  }, []);

  const loadRecentCompanies = async () => {
    try {
      const storedCompanies = await AsyncStorage.getItem('recentCompanies');
      if (storedCompanies) {
        setRecentCompanies(JSON.parse(storedCompanies));
      }
    } catch (error) {
      console.error('Error loading recent companies:', error);
    }
  };

  const saveCompanyToRecent = async (company: string) => {
    try {
      const updatedCompanies = [
        company,
        ...recentCompanies.filter(name => name !== company)
      ].slice(0, 5);
      
      setRecentCompanies(updatedCompanies);
      await Keychain.setGenericPassword('recentCompanies', JSON.stringify(updatedCompanies));
    } catch (error) {
      console.error('Error saving recent company:', error);
    }
  };

  const validateInputs = () => {
    if (!loginIdentifier || !password) {
      Alert.alert('Error', 'Please enter email/username and password');
      return false;
    }

    if (loginType === 'employee' && !companyName) {
      Alert.alert('Error', 'Please enter your company name');
      return false;
    }

    return true;
  };

  const handleLogin = async () => {
    if (!validateInputs()) return;

    setIsLoading(true);

    try {
      if (loginType === 'admin') {
        await handleAdminLogin();
      } else {
        await handleEmployeeLogin();
      }
    } catch (error) {
      Alert.alert('Connection Error', 'Failed to connect to server');
    } finally {
      setIsLoading(false);
    }
  };

  const handleAdminLogin = async () => {
    const response = await fetch(`${API_CONFIG.BASE_URL}${ENDPOINTS.AUTH.ADMIN_LOGIN}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        email: loginIdentifier.trim().toLowerCase(),
        password: password
      }),
    });

    const userData = await response.json();
    
    if (response.ok) {
      await login(userData.token, { 
        ...userData.user, 
        type: 'user',
        company_id: userData.user.company_id 
      });
      Alert.alert('Success', `Welcome Admin ${userData.user.email}!`);
    } else {
      Alert.alert('Error', userData.error || 'Admin login failed');
    }
  };

  const handleEmployeeLogin = async () => {
    const response = await fetch(`${API_CONFIG.BASE_URL}${ENDPOINTS.AUTH.EMPLOYEE_LOGIN}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        login: loginIdentifier.trim(),
        password: password,
        company_name: companyName.trim()
      }),
    });

    const employeeData = await response.json();
    
    if (response.ok) {
      await saveCompanyToRecent(companyName);
      await employeeLogin(employeeData.token, { 
        ...employeeData.employee, 
        type: 'employee',
        company_id: employeeData.employee.company_id,
        company_name: employeeData.employee.company_name
      });
      Alert.alert('Success', `Welcome ${employeeData.employee.first_name}!`);
    } else {
      Alert.alert('Error', employeeData.error || 'Login failed');
    }
  };

  return (
    <ScrollView contentContainerStyle={styles.scrollContainer}>
      <View style={styles.container}>
        <View style={styles.backgroundContainer}>
          <Svg height="100%" width="100%" style={styles.backgroundSvg}>
            <Defs>
              <LinearGradient id="grad" x1="0%" y1="0%" x2="100%" y2="100%">
                <Stop offset="0.1" stopColor="#ffbf00" stopOpacity="1" />
                <Stop offset="0.3" stopColor="#ff8c00" stopOpacity="1" />
                <Stop offset="0.7" stopColor="#04ded3" stopOpacity="1" />
                <Stop offset="0.5" stopColor="#0463de" stopOpacity="1" />
                <Stop offset="1" stopColor="#02b30e" stopOpacity="1" />
              </LinearGradient>
            </Defs>
            <Rect x="0" y="0" width="100%" height="100%" fill="url(#grad)" />
          </Svg>
        </View>

        <View style={styles.formContainer}>
          <Text style={styles.title}>
            {loginType === 'admin' ? 'Admin Login' : 'Employee Login'}
          </Text>
          
          <View style={styles.toggleContainer}>
            <TouchableOpacity 
              style={[styles.toggleButton, loginType === 'employee' && styles.toggleButtonActive]}
              onPress={() => {
                setLoginType('employee');
                setLoginIdentifier('');
                setPassword('');
                setCompanyName('');
              }}
            >
              <Text style={[styles.toggleText, loginType === 'employee' && styles.toggleTextActive]}>
                Employee
              </Text>
            </TouchableOpacity>
            <TouchableOpacity 
              style={[styles.toggleButton, loginType === 'admin' && styles.toggleButtonActive]}
              onPress={() => {
                setLoginType('admin');
                setLoginIdentifier('');
                setPassword('');
                setCompanyName('');
              }}
            >
              <Text style={[styles.toggleText, loginType === 'admin' && styles.toggleTextActive]}>
                Admin
              </Text>
            </TouchableOpacity>
          </View>

          {loginType === 'employee' && (
            <View style={styles.companySection}>
              <Text style={styles.label}>Company Name</Text>
              <TextInput
                style={styles.input}
                placeholder="Enter your company name"
                value={companyName}
                onChangeText={setCompanyName}
                autoCapitalize="words"
                placeholderTextColor={'#000'}
              />

              {recentCompanies.length > 0 && (
                <View style={styles.recentContainer}>
                  <Text style={styles.recentLabel}>Recent:</Text>
                  <View style={styles.recentList}>
                    {recentCompanies.map((company) => (
                      <TouchableOpacity
                        key={company}
                        style={styles.recentButton}
                        onPress={() => setCompanyName(company)}
                      >
                        <Text style={styles.recentText}>{company}</Text>
                      </TouchableOpacity>
                    ))}
                  </View>
                </View>
              )}
            </View>
          )}

          <View style={styles.formSection}>
            <Text style={styles.label}>
              {loginType === 'admin' ? 'Email' : 'Email or Username'}
            </Text>
            <TextInput
              style={styles.input}
              placeholder={loginType === 'admin' ? "Enter admin email" : "Enter email or username"}
              value={loginIdentifier}
              onChangeText={setLoginIdentifier}
              autoCapitalize="none"
              keyboardType={loginType === 'admin' ? "email-address" : "default"}
              placeholderTextColor={'#000'}
            />

            <Text style={styles.label}>Password</Text>
            <View style={styles.passwordContainer}>
              <TextInput
                style={styles.passwordInput}
                placeholder="Enter your password"
                value={password}
                onChangeText={setPassword}
                secureTextEntry={!showPassword}
                placeholderTextColor={'#000'}
              />
              <TouchableOpacity
                style={styles.showPasswordButton}
                onPress={() => setShowPassword(!showPassword)}
              >
                <Text style={styles.showPasswordText}>
                  {showPassword ? 'Hide' : 'Show'}
                </Text>
              </TouchableOpacity>
            </View>
            
            <TouchableOpacity
              style={[styles.primaryButton, isLoading && styles.buttonDisabled]}
              onPress={handleLogin}
              disabled={isLoading}
            >
              {isLoading ? (
                <ActivityIndicator color="#fff"/>
              ) : (
                <Text style={styles.buttonText}>
                  {loginType === 'admin' ? 'Admin Login' : 'Employee Login'}
                </Text>
              )}
            </TouchableOpacity>

            {loginType === 'employee' && (
              <TouchableOpacity
                style={styles.secondaryButton}
                onPress={() => navigation.navigate("NFCLogin")}
              >
                <Text style={styles.buttonText}>Login With RFID Card</Text>
              </TouchableOpacity>
            )}

            {loginType === 'admin' && (
              <TouchableOpacity 
                style={styles.linkButton}
                onPress={() => navigation.navigate("Register")}
              >
                <Text style={styles.linkText}>Create new company and admin account</Text>
              </TouchableOpacity>
            )}
          </View>
        </View>
      </View>
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  scrollContainer: {
    flexGrow: 1,
  },
  container: {
    flex: 1,
    alignItems: "center",
    justifyContent: "center",
    paddingVertical: 20,
  },
  backgroundContainer: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
  },
  backgroundSvg: {
    flex: 1,
    width : '100%',
    height : '100%',
  },
  formContainer: {
    backgroundColor: '#ffffff',
    padding: 25,
    borderRadius: 45,
    width: '95%',
    maxWidth: 400,
    borderRightWidth: 4,
    borderRightColor: '#fc0303',
    borderLeftWidth: 4,
    borderLeftColor: '#fc0303',
    marginVertical: 20,
  },
  title: {
    fontSize: 28,
    fontWeight: "bold",
    marginBottom: 20,
    textAlign: 'center',
    color: '#333',
  },
  toggleContainer: {
    flexDirection: 'row',
    borderWidth: 2,
    borderColor: '#007AFF',
    borderRadius: 10,
    marginBottom: 10,
    overflow: 'hidden',
  },
  toggleButton: {
    flex: 1,
    padding: 12,
    alignItems: 'center',
    backgroundColor: 'white',
  },
  toggleButtonActive: {
    backgroundColor: '#007AFF',
  },
  toggleText: {
    fontSize: 14,
    fontWeight: '600',
    color: '#007AFF',
  },
  toggleTextActive: {
    color: 'white',
  },
  companySection: {
    marginBottom: 0,
  },
  formSection: {
    marginBottom: 15,
  },
  label: {
    fontSize: 16,
    color: '#666',
    marginBottom: 8,
    fontWeight: '500',
  },
  input: {
    borderWidth: 2,
    borderColor: '#000',
    borderRadius: 10,
    padding: 15,
    marginBottom: 10,
    fontSize: 16,
    backgroundColor: 'white',
  },
  passwordContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    borderWidth: 2,
    borderColor: '#000',
    borderRadius: 10,
    marginBottom: 15,
    backgroundColor: 'white',
  },
  passwordInput: {
    flex: 1,
    padding: 15,
    fontSize: 16,
    color: "#000"
  },
  showPasswordButton: {
    padding: 15,
    paddingLeft: 10,
  },
  showPasswordText: {
    color: '#007AFF',
    fontWeight: '600',
  },
  primaryButton: {
    backgroundColor: '#007AFF',
    padding: 15,
    borderRadius: 10,
    alignItems: 'center',
    marginBottom: 10,
  },
  secondaryButton: {
    backgroundColor: '#FF9500',
    padding: 15,
    borderRadius: 10,
    alignItems: 'center',
    marginBottom: 10,
  },
  buttonDisabled: {
    backgroundColor: '#CCCCCC',
  },
  buttonText: {
    color: '#fff',
    fontSize: 16,
    fontWeight: 'bold',
  },
  linkButton: {
    alignItems: 'center',
    padding: 10,
  },
  linkText: {
    color: '#007AFF',
    fontSize: 16,
    textDecorationLine: 'underline',
  },
  recentContainer: {
    marginBottom: 10,
  },
  recentLabel: {
    fontSize: 14,
    color: '#666',
    marginBottom: 8,
  },
  recentList: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: 8,
  },
  recentButton: {
    backgroundColor: '#f0f0f0',
    paddingHorizontal: 12,
    paddingVertical: 6,
    borderRadius: 6,
  },
  recentText: {
    fontSize: 12,
    color: '#333',
  },
});